<script setup lang="ts">import{ref,computed,onMounted,watch}from 'vue';import{useRoute}from 'vue-router';import{lab,load}from '../stores/research';import{useTask}from '../hooks/useTask';import{usePolling}from '../hooks/usePolling';import{fmt,bearing}from '../utils/format';import{fitStates}from '../constants/enums';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import RunSelect from '../components/RunSelect.vue';import PolarPlot from '../components/PolarPlot.vue';import EnergyPlot from '../components/EnergyPlot.vue';const route=useRoute(),id=ref(Number(route.query.run)||0),{error,execute}=useTask(),run=computed(()=>lab.runs.find(r=>r.id===id.value));onMounted(()=>execute(async()=>{await load();id.value=id.value||lab.runs.find(r=>r.status==='completed')?.id||0}));watch(()=>route.query.run,v=>{if(v)id.value=Number(v)});usePolling(()=>{if(run.value&&['queued','running'].includes(run.value.status))execute(load)});</script><template><PageHeading index="04" title="均值有边界，差异有前提。" text="从形状读到合向量，再看标签置换。完整研究包含原始输入快照、分组、seed与SHA256。"><RouterLink v-if="run?.status==='completed'" class="outline" :to="'/notes?run='+run.id">建立观察说明 ↗</RouterLink></PageHeading><ErrorNotice :message="error" @retry="execute(load)"/><RunSelect v-model="id" :runs="lab.runs"/><template v-if="run?.status==='completed'&&run.result.a&&run.result.b&&run.result.energy"><div class="result-top"><PolarPlot :a="run.result.a" :b="run.result.b"/><section class="circular-reading"><p class="eyebrow">CIRCULAR MOMENTS / VON MISES</p><article v-for="(g,i) in [run.result.a,run.result.b]"><h2>{{i?'B':'A'}}组 · {{g.n}}条</h2><dl><div><dt>圆周均值</dt><dd>{{bearing(g.mean_bearing)}}</dd></div><div><dt>合向量 R</dt><dd>{{fmt(g.resultant,4)}}</dd></div><div><dt>二阶合向量 R₂</dt><dd>{{fmt(g.second_resultant,4)}}</dd></div><div><dt>集中度 κ</dt><dd>{{fmt(g.kappa,3)}}</dd></div></dl><p class="fit-state">{{fitStates[g.fit_status]}}</p><p class="plot-note">{{g.warning}}</p></article></section></div><div class="energy-summary"><div><p class="eyebrow">DISTRIBUTION ENERGY</p><h2>{{fmt(run.result.energy.statistic,5)}}</h2><p>单位圆弦距离V统计量</p></div><div><p class="eyebrow">PERMUTATION P</p><h2>{{fmt(run.result.energy.p_value,4)}}</h2><p>{{run.result.energy.permutations}}次置换 / seed{{run.seed}}</p></div><p>{{run.result.interpretation}}</p></div><EnergyPlot :energy="run.result.energy"/><section class="register"><div class="section-title"><h2>同一扇区，观测与单峰描述分列</h2><span>每格角度为左闭右开；最后一格不包括360°</span></div><div class="table-wrap"><table><thead><tr><th>方向扇区</th><th>A计数</th><th>A比例</th><th>A模型概率</th><th>B计数</th><th>B比例</th><th>B模型概率</th></tr></thead><tbody><tr v-for="(h,i) in run.result.a.histogram"><td>{{h.lower}}–{{h.upper}}°</td><td>{{h.count}}</td><td>{{fmt(h.proportion,4)}}</td><td>{{fmt(h.fitted_probability,4)}}</td><td>{{run.result.b.histogram[i].count}}</td><td>{{fmt(run.result.b.histogram[i].proportion,4)}}</td><td>{{fmt(run.result.b.histogram[i].fitted_probability,4)}}</td></tr></tbody></table></div><p class="fingerprint">输入SHA256 {{run.result.fingerprint}}</p><details><summary>读取完整JSON与输入快照</summary><pre>{{JSON.stringify(run.result,null,2)}}</pre></details></section></template><div v-else class="empty"><h2>{{run?.status==='failed'?'研究未完成':'等待圆周研究结果'}}</h2><p>{{run?.error||'队列中自动刷新；也可重新读取或建立第一份研究。'}}</p><button class="outline" @click="execute(load)">重新读取</button><RouterLink to="/configure">研究配置 ↗</RouterLink></div></template>
